                "ID:{0} SID:{1} SYM:{2} ACT:{3}",
                PanelValue(entry != null ? entry.ItemId : "", "-"),
                PanelValue(entry != null ? entry.Sid : "", "NO_SID"),
                PanelValue(entry != null ? entry.Symbol : "", "?"),
