            {
                { "initialEquity", _backtestExportInitialEquity },
                { "riskPercent", GetEffectiveMaxRiskPercent() },
                { "fixedRiskAmount", null },
                { "compoundEquity", false },
                { "spreadAbs", 0 },
                { "spreadBps", 0 },
                { "commissionFlat", 0 },
                { "commissionPerUnit", 0 },
                { "breakEvenAtR", null },
                { "partialAtR", null },
                { "partialCloseFraction", 1.0 },
                { "maxBarsInTrade", 0 },
                { "brokerCalibration", null },
